"""Inspect the workspace: list files and dump any SQLite database schemas."""
import os
import sqlite3

HERE = os.path.dirname(os.path.abspath(__file__))

print("Files in workspace:")
for name in sorted(os.listdir(HERE)):
    print(" -", name)

db_files = [
    name
    for name in os.listdir(HERE)
    if name.lower().endswith((".db", ".sqlite", ".sqlite3"))
]

if not db_files:
    print("\nNo database files found in the workspace.")
else:
    for name in db_files:
        path = os.path.join(HERE, name)
        print(f"\n=== {name} ===")
        try:
            with sqlite3.connect(path) as conn:
                conn.row_factory = sqlite3.Row
                cur = conn.cursor()
                cur.execute(
                    "SELECT name, type FROM sqlite_master "
                    "WHERE type IN ('table', 'view') ORDER BY name"
                )
                objects = cur.fetchall()
                if not objects:
                    print("  (no tables or views)")
                for obj in objects:
                    print(f"  {obj['type']}: {obj['name']}")
                    if obj["type"] == "table":
                        cur.execute(f"PRAGMA table_info({obj['name']})")
                        for col in cur.fetchall():
                            print(
                                f"    column: {col['name']} {col['type']} "
                                f"notnull={col['notnull']} default={col['dflt_value']!r} "
                                f"pk={col['pk']}"
                            )
                        cur.execute(f"SELECT COUNT(*) AS n FROM {obj['name']}")
                        print(f"    rows: {cur.fetchone()['n']}")
        except Exception as exc:
            print(f"  ERROR: {exc}")

